"""In-process notification registration for registered resources.

A notification record pairs a channel with a target and a message. Every
submission creates an independent record: records are never deduplicated,
updated or deleted, and are kept per resource in submission order. Nothing
here is persisted: stopping or restarting the service clears every
notification, and no files are written.
"""

from __future__ import annotations

import uuid
from dataclasses import dataclass

#: Length caps, counted in Unicode code points.
MAX_CHANNEL_LENGTH = 64
MAX_TARGET_LENGTH = 256
MAX_MESSAGE_LENGTH = 2048

#: Fields accepted by the registration request; anything else is rejected.
_ALLOWED_FIELDS = frozenset({"channel", "target", "message"})
_REQUIRED_FIELDS = ("channel", "target", "message")


class NotificationValidationError(ValueError):
    """A notification payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


@dataclass(frozen=True, slots=True)
class Notification:
    """A single notification record registered against a resource."""

    id: str
    channel: str
    target: str
    message: str

    def to_dict(self) -> dict[str, object]:
        return {
            "id": self.id,
            "channel": self.channel,
            "target": self.target,
            "message": self.message,
        }


def _required_string(value: object, field: str, limit: int) -> str:
    """Validate a required non-empty string bounded by ``limit`` code points."""

    label = field.capitalize()
    if not isinstance(value, str):
        raise NotificationValidationError(f"Field {field!r} must be a string.")
    if not value:
        raise NotificationValidationError(
            f"Field {field!r} must not be empty."
        )
    if len(value) > limit:
        raise NotificationValidationError(
            f"{label} must not exceed {limit} Unicode code points."
        )
    return value


def build_notification_fields(payload: object) -> tuple[str, str, str]:
    """Validate a decoded JSON payload and return ``(channel, target, message)``.

    All three fields are required non-empty strings bounded by their
    respective length caps; unknown fields are rejected.
    """

    if not isinstance(payload, dict):
        raise NotificationValidationError(
            "Request body must be a JSON object."
        )

    unknown_fields = set(payload) - _ALLOWED_FIELDS
    if unknown_fields:
        raise NotificationValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    for field in _REQUIRED_FIELDS:
        if field not in payload:
            raise NotificationValidationError(
                f"Missing required field: {field!r}."
            )

    channel = _required_string(
        payload["channel"], "channel", MAX_CHANNEL_LENGTH
    )
    target = _required_string(payload["target"], "target", MAX_TARGET_LENGTH)
    message = _required_string(
        payload["message"], "message", MAX_MESSAGE_LENGTH
    )
    return channel, target, message


class NotificationStore:
    """Process-local, submission-ordered notification storage per resource."""

    def __init__(self) -> None:
        # resource id -> notifications in submission order.
        self._records: dict[str, list[Notification]] = {}

    def reset(self) -> None:
        self._records = {}

    def remove_resource(self, resource_id: str) -> None:
        """Remove every notification recorded for a resource.

        An unknown id is a no-op.
        """

        self._records.pop(resource_id, None)

    def add(self, resource_id: str, payload: object) -> Notification:
        """Validate and append a notification for ``resource_id``.

        Every call creates an independent record; identical submissions are
        never merged or deduplicated. Raises
        :class:`NotificationValidationError` for an invalid payload.
        """

        channel, target, message = build_notification_fields(payload)
        record = Notification(
            id=uuid.uuid4().hex,
            channel=channel,
            target=target,
            message=message,
        )
        self._records.setdefault(resource_id, []).append(record)
        return record

    def list_for(self, resource_id: str) -> list[Notification]:
        """Return a resource's notifications in submission order."""

        return list(self._records.get(resource_id, ()))

def _handle_notifications_post(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    raw = _read_body(environ)
    if not raw:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body is empty.",
        )
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be valid UTF-8 JSON.",
        )

    # Validate the whole body before touching any store, so a bad request
    # can never leave a partial record and always answers 400 (even for a
    # resource that does not exist).
    try:
        build_notification_fields(payload)
    except NotificationValidationError as exc:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            exc.message,
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    record = notification_store.add(raw_id, payload)
    return _json_response(
        start_response,
        "201 Created",
        record.to_dict(),
        trailing_newline=True,
    )


def _handle_notifications_get(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )
    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    records = notification_store.list_for(raw_id)
    return _json_response(
        start_response,
        "200 OK",
        {"notifications": [record.to_dict() for record in records]},
        trailing_newline=True,
    )


def _handle_notifications(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method == "POST":
        return _handle_notifications_post(environ, raw_id, start_response)
    if method == "GET":
        return _handle_notifications_get(environ, raw_id, start_response)
    return _error(
        start_response,
        "405 Method Not Allowed",
        "method_not_allowed",
        f"Method {method} is not allowed for this path.",
        allowed="GET, POST",
    )


def _parse_notifications_summary_query(
    query_string: str,
) -> tuple[str | None, str | None]:
    """Parse the optional, single ``channel`` query parameter.

    Returns ``(channel, None)`` -- with ``None`` when the parameter is
    absent -- or ``(None, message)`` for an unknown parameter, a repeated
    ``channel`` or an empty value. The channel value is matched verbatim
    against notification channels: case-sensitive, no trimming.
    """

    pairs = parse_qsl(
        query_string, keep_blank_values=True, strict_parsing=False
    )
    channel: str | None = None
    for key, value in pairs:
        if key != "channel":
            return None, f"Unknown query parameter: {key!r}."
        if channel is not None:
            return None, "Query parameter 'channel' must not be repeated."
        if value == "":
            return None, "Channel must not be empty."
        channel = value
    return channel, None


def _handle_notifications_summary(
    method: str,
    environ: dict[str, Any],
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "GET":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    # The summary is read-only: a declared non-empty (or malformed) body is
    # a bad request without consulting any business data. An omitted header
    # and an explicit zero length are accepted as an empty body.
    body_error = _bodyless_request_error(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )

    # Only the optional ``channel`` filter is accepted; unknown or repeated
    # parameters and an empty value are rejected before any data is read.
    channel, query_error = _parse_notifications_summary_query(
        str(environ.get("QUERY_STRING", ""))
    )
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    # Computed on the fly from the current stores: entries unfold in
    # resource registration order, and within one resource the records keep
    # their submission order. Resources without notifications are skipped
    # silently. Each entry puts the owning resource id first, followed by
    # the same fields (and key order) as a single notification record.
    # Nothing is recorded and no state is touched.
    notifications: list[dict[str, object]] = []
    for resource in store.list_all():
        for record in notification_store.list_for(resource.id):
            if channel is not None and record.channel != channel:
                continue
            notifications.append(
                {"resource_id": resource.id, **record.to_dict()}
            )
    return _json_response(
        start_response,
        "200 OK",
        notifications,
        trailing_newline=True,
    )


def _handle_cache_layer_post(
    environ: dict[str, Any], raw_digest: str, start_response: StartResponse
) -> Iterable[bytes]:
    # The path digest is validated before anything else so a malformed
    # digest is rejected without reading the request body.
    if _DIGEST_PATTERN.fullmatch(raw_digest) is None:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Layer digest must be a 64-character hexadecimal string.",
        )
    digest = raw_digest.lower()

    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    content_type = str(environ.get("CONTENT_TYPE", ""))
    if content_type.lower() != _OCTET_STREAM_CONTENT_TYPE:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Content-Type must be application/octet-stream.",
        )

def _json_response(
    start_response: StartResponse,
    status: str,
    payload: object,
    *,
    extra_headers: list[tuple[str, str]] | None = None,
    trailing_newline: bool = False,
) -> Iterable[bytes]:
    body = json.dumps(
        payload,
        ensure_ascii=False,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    if trailing_newline:
        body += b"\n"
    headers = [
        ("Content-Type", "application/json; charset=utf-8"),
        ("Content-Length", str(len(body))),
    ]
    if extra_headers:
        headers.extend(extra_headers)
    start_response(status, headers)
    return [body]


def _error(
    start_response: StartResponse,
    status: str,
    code: str,
    message: str,
    *,
    allowed: str | None = None,
    trailing_newline: bool = True,
    extra_headers: list[tuple[str, str]] | None = None,
) -> Iterable[bytes]:
    headers = list(extra_headers) if extra_headers else []
    if allowed is not None:
        headers.append(("Allow", allowed))
    return _json_response(
        start_response,
        status,
        {"error": code, "message": message},
        extra_headers=headers,
        trailing_newline=trailing_newline,
    )


def _resource_response(
    start_response: StartResponse, status: str, resource: Resource
) -> Iterable[bytes]:
    return _json_response(
        start_response,
        status,
        resource.to_dict(),
        trailing_newline=True,
    )


def _read_body(environ: dict[str, Any]) -> bytes:
    try:
        length = int(environ.get("CONTENT_LENGTH") or 0)
    except (TypeError, ValueError):
        length = 0
    if length <= 0:
        return b""
    return environ["wsgi.input"].read(length)


def _handle_resources_post(
    environ: dict[str, Any], start_response: StartResponse
) -> Iterable[bytes]:
    raw = _read_body(environ)
    if not raw:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body is empty.",
        )
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be valid UTF-8 JSON.",
        )

    try:
        created, existing = store.add(payload)
    except ResourceValidationError as exc:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            exc.message,
        )

    if existing is not None:
        # Never overwrite or merge with the original record.
        return _error(
            start_response,
            "409 Conflict",
            "duplicate_resource",
            "A resource with the same category, name and digest already exists.",
        )

    assert created is not None
    return _resource_response(start_response, "201 Created", created)


def _remove_resource_cascade(resource_id: str) -> None:
    """Remove every record keyed by ``resource_id`` across all stores.

    Alerts, exemptions, SBOM and license data, provenance, policies,
    signatures, notifications, lifecycle state, chunk sessions with their
    assembled bytes, cross-repository references and dependency edges all
    disappear with the resource; derived read-only views (advisory
    summaries, component views, admission previews, risk scores) are
    computed on the fly and therefore reflect the removal immediately.
    Mirror sources, cache entries and other resources are never touched.
    """

    vulnerability_store.remove_resource(resource_id)
    vulnerability_exception_store.remove_resource(resource_id)
    sbom_store.remove_resource(resource_id)
    provenance_store.remove_resource(resource_id)
    policy_store.remove_resource(resource_id)
    signature_store.remove_resource(resource_id)
    notification_store.remove_resource(resource_id)
    lifecycle_store.remove(resource_id)
    content_store.remove(resource_id)
    cross_reference_store.remove_resource(resource_id)
    store.remove(resource_id)


def _handle_resource_item(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method not in ("GET", "DELETE"):
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="DELETE, GET",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )

    if method == "GET":
        resource = store.get(raw_id)
        if resource is None:
            return _error(
                start_response,
                "404 Not Found",
                "resource_not_found",
                "No resource exists with the requested id.",
            )
        return _resource_response(start_response, "200 OK", resource)

    # DELETE: a bodyless, parameterless request that unregisters the
    # resource and cascades to every record stored under its id.
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )
    body_error = _bodyless_request_error(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )

    resource = store.get(raw_id)
    if resource is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    _remove_resource_cascade(raw_id)
    return _resource_response(start_response, "200 OK", resource)


def _validate_path_id(raw_id: str) -> str | None:
    """Return a stable error message for an invalid path id, else ``None``."""

    if not raw_id:
        return "Resource id must not be empty."
    if "/" in raw_id or "\\" in raw_id:
        return "Resource id must not contain path separators."
    return None


def _decode_reference_segment(raw_segment: str, label: str) -> tuple[str, str | None]:
    """Percent-decode one cross-reference item path segment.

    Returns ``(decoded, None)`` or ``(None, message)``. The segment is
    decoded as a path segment and then matched verbatim against the stored
    value; an empty segment or one that decodes to contain a path
    separator (``/`` or ``\\``, including ``%2F``/``%5C``) is rejected.
    """

    decoded = unquote(raw_segment)
    if not decoded:
        return None, f"{label} path segment must not be empty."
    if "/" in decoded or "\\" in decoded:
        return None, f"{label} path segment must not contain path separators."
    return decoded, None


def _query_parameter_error(environ: dict[str, Any]) -> str | None:
    """Reject any query parameter on endpoints that declare none."""

    query_string = str(environ.get("QUERY_STRING", ""))
    if parse_qsl(query_string, keep_blank_values=True):
        return "This endpoint does not accept query parameters."
    return None


def _handle_dependencies_post(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )

    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    raw = _read_body(environ)
    if not raw:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body is empty.",
        )
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be valid UTF-8 JSON.",
        )

    if not isinstance(payload, dict):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be a JSON object.",
        )
    unknown_fields = set(payload) - {"dependency_id"}
    if unknown_fields:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            f"Unknown field: {sorted(unknown_fields)[0]!r}.",
        )

class ResourceStore:
    """Process-local, insertion-ordered resource storage."""

    def __init__(self) -> None:
        self._resources: list[Resource] = []
        self._by_id: dict[str, Resource] = {}
        self._key_to_id: dict[tuple[str, str, str], str] = {}
        # resource id -> ids it directly depends on, and the reverse view.
        # Insertion-ordered dicts stand in for ordered sets: membership stays
        # O(1) while iteration remembers the order in which each relation was
        # established, which the global graph snapshot reports.
        self._dependencies: dict[str, dict[str, None]] = {}
        self._dependents: dict[str, dict[str, None]] = {}

    def reset(self) -> None:
        self._resources.clear()
        self._resources = []
        self._by_id = {}
        self._key_to_id = {}
        self._dependencies = {}
        self._dependents = {}

    def list_all(self) -> list[Resource]:
        return list(self._resources)

    def query(
        self,
        *,
        category: str | None = None,
        name: str | None = None,
        digest: str | None = None,
    ) -> list[Resource]:
        """Return matching resources in creation order.

        ``category`` is compared case-insensitively, ``name`` is an exact
        string match and ``digest`` is compared against the stored lowercase
        form. Multiple conditions are AND-ed together.
        """

def _bodyless_request_error(environ: dict[str, Any]) -> str | None:
    """Reject a bodyless endpoint (cache DELETE) that declares a body.

    Unlike admission, this also treats an empty-string ``Content-Length``
    as no body: a real WSGI server seeds ``CONTENT_LENGTH`` with ``''``
    for requests that omit the header entirely (e.g. curl's bodyless
    DELETE), so only a declared positive or malformed length is rejected.
    An explicit ``Content-Length: 0`` is an empty body and is accepted.
    """

    raw_length = environ.get("CONTENT_LENGTH")
    if raw_length is None or raw_length == "":
        return None
    if (
        not isinstance(raw_length, str)
        or _NON_NEGATIVE_INT_PATTERN.fullmatch(raw_length) is None
        or int(raw_length) > 0
    ):
        return "This endpoint does not accept a request body."
    return None


