if path == "/fix-coverage":
    # Global per-component fix coverage summary aggregated by alert
    # component name; the handler answers the 405 (Allow: GET) for
    # every other method.
    return _handle_fix_coverage(method, environ, start_response)

if path == "/fix-coverage-progress":
    # Global per-resource fix coverage progress summary; the handler
    # answers the 405 (Allow: GET) for every other method.
    return _handle_fix_coverage_progress(
        method, environ, start_response
    )

if path == "/severity-coverage":
    # Global fix coverage summary aggregated by alert severity
    # level; the handler answers the 405 (Allow: GET) for every
    # other method.
    return _handle_severity_coverage(
        method, environ, start_response
    )

if path == "/advisory-fix-progress":
    # Global fix progress summary aggregated by advisory number;
    # the handler answers the 405 (Allow: GET) for every other
    # method.
    return _handle_advisory_fix_progress(
        method, environ, start_response
    )

if path == "/advisory-fix-gaps":
    # Global fix gap summary aggregated by advisory/component pair;
    # the handler answers the 405 (Allow: GET) for every other
    # method.
    return _handle_advisory_fix_gaps(
        method, environ, start_response
    )

if path.startswith("/advisories/"):
    # The identifier segment is validated by the handler; an
    # embedded separator or an empty segment is a bad request. A
    # trailing "/fixes" segment selects the per-advisory component
    # fix view instead of the alert detail view.
    tail = path[len("/advisories/"):]
    if tail.endswith("/fixes"):
        return _handle_advisory_fixes(
            method, environ, tail[: -len("/fixes")], start_response
        )
    return _handle_advisory_item(
        method, environ, tail, start_response
    )

if path == "/notifications":
    # Global notification summary; the handler answers the 405
    # (Allow: GET) for every other method.
    return _handle_notifications_summary(
        method, environ, start_response
    )

if path == "/resources":
    if method == "GET":
        return _handle_resources_get(environ, start_response)
    if method == "POST":
        return _handle_resources_post(environ, start_response)
    return _error(
        start_response,
        "405 Method Not Allowed",
        "method_not_allowed",
        f"Method {method} is not allowed for this path.",
        allowed="GET, POST",
    )

if path == "/policies":
    return _handle_default_policy(method, environ, start_response)

if path == "/cache":
    return _handle_cache_root(method, environ, start_response)

if path == "/cache/status":
    return _handle_cache_status(method, environ, start_response)

if path.startswith("/cache/layers/"):
    tail = path[len("/cache/layers/"):]
    if tail.endswith("/check"):
        # Read-only write pre-check for the layer path; the digest
        # segment is validated by the handler, so an embedded
        # separator is rejected there as a bad request.
        return _handle_cache_layer_check(
            method,
            environ,
            tail[: -len("/check")],
            start_response,
        )
    return _handle_cache_layer(
        method, environ, tail, start_response
    )

if path == "/mirrors":
    return _handle_mirrors(method, environ, start_response)

if path.startswith("/mirrors/"):
    suffix = path[len("/mirrors/"):]
    marker = "/pull/"
    marker_index = suffix.find(marker)
    if marker_index >= 0:
        # Split on the pull marker even when the id segment embeds a
        # separator, so the pull handler can reject the id as a bad
        # request instead of treating the path as an unknown item.
        return _handle_mirror_pull(
            method,
            environ,
